async function main() {
  await mkdir(outDir, { recursive: true });
  let ok = 0;
  const failed = [];

  for (const photo of photos) {
    try {
      const res = await fetch(photo.url);
      if (!res.ok) {
        throw new Error(`HTTP ${res.status}`);
      }
      const buffer = Buffer.from(await res.arrayBuffer());
      await writeFile(path.join(outDir, photo.targetFilename), buffer);
      ok += 1;
      console.log(`OK   ${photo.targetFilename}  (${photo.fullName})`);
    } catch (err) {
      failed.push(photo);
      console.log(`FAIL ${photo.targetFilename}  (${photo.fullName}) - ${err.message}`);
    }
  }

  console.log();
  console.log(`Downloaded ${ok}/${photos.length} photos to public/mentors/.`);
  if (failed.length > 0) {
    console.log(
      `${failed.length} failed -- likely because the signed Airtable URLs expired. Ask Claude to re-export fresh URLs and regenerate this script.`,
    );
  }
}

main();
